// Generated by setup-boss-progression/unlocks/scrolls.py: reading a boss scroll unlocks its tier for that player.
var MegaBossUnlocks = Java.loadClass('mega.bossunlocks.MegaBossUnlocks')
var SCROLL_OPENS = {"naga": "книги заклинань Iron’s Spells на 5–8 слотів і книгу початківця Ars Nouveau", "hydra": "книги Iron’s на 10 слотів, книгу мага Ars, броню шкіл магії Iron’s і стихійну броню Ars Elemental", "wither": "книги Iron’s на 12 слотів, книгу архімага Ars, незеритову зброю Epic Fight і WoM, броню незеритового мага та легендарну зброю Iron’s", "ignis": "очищений обсидіан, сплав затемнення, Ruinfighter і Duskfire"}
Object.keys(SCROLL_OPENS).forEach(gate => {
  ItemEvents.rightClicked('kubejs:boss_unlock_scroll_' + gate, event => {
    var player = event.player
    if (player.level.isClientSide()) return
    if (!MegaBossUnlocks.unlock(player, gate)) {
      player.setStatusMessage(Text.gold('Цей рівень уже відкрито для вас.'))
      event.cancel()
      return
    }
    event.item.shrink(1)
    var at = 'execute as ' + player.username + ' at @s run '
    event.server.runCommandSilent(at + 'playsound minecraft:item.totem.use player @s ~ ~ ~ 1 1')
    event.server.runCommandSilent(at + 'playsound minecraft:ui.toast.challenge_complete player @s ~ ~ ~ 1 1')
    event.server.runCommandSilent(at + 'particle minecraft:totem_of_undying ~ ~1 ~ 0.6 1 0.6 0.5 120 force @s')
    player.tell(Text.gold('Відкрито: ' + SCROLL_OPENS[gate] + '.'))
    player.sendData('mega_boss_unlock', { item: 'kubejs:boss_unlock_scroll_' + gate })
    event.cancel()
  })
})
